// 720 Degrees - native Windows port (C++ / SDL3).
//
// The game logic is the original arcade program statically translated to C++
// (src/game, generated by tools/t11_to_cpp.py and tools/m6502_to_cpp.py); graphics,
// sound chips and controls are implemented natively here and in src/board.
//
// Controls (keyboard):
//   Arrows / WASD ....... point the skater (8 directions)
//   Q / E ............... rotate counter-clockwise / clockwise
//   Space / Z ........... Jump        Left Ctrl / X ........ Kick
//   5 / 6 ............... insert coin (left / right)
//   F1 .................. help overlay        F2 ........... service mode (test switch)
//   F3 .................. reset               F11 / Alt+Enter fullscreen
//   P ................... pause               Esc ........... release mouse / quit
// Mouse (click window to capture): horizontal movement rotates, buttons = Jump / Kick.
// Gamepad: left stick or d-pad points the skater, A = Jump, B/X = Kick, Back = coin.
#include <SDL3/SDL.h>
#include <SDL3/SDL_main.h>
#include "nativemachine.h"
#include "soundchips.h"
#include "controls.h"
#include "modloader.h"
#include "audioout.h"
#include <cstdio>
#include <cstring>
#include <cmath>
#include <string>
#include <vector>
#include <fstream>

namespace {

struct Options {
	std::string roms;
	bool fullscreen = false;
	int scale = 2;
	bool smooth = false;
	int dsw0 = 0x00, dsw1 = 0x55;
	bool invert_rotation = false;
	std::vector<std::string> mods;
	bool no_mods = false;
	double quit_after = 0;               // testing: quit after this many seconds and print audio stats
};

std::string find_roms(const std::string &requested)
{
	if (!requested.empty()) return requested;
	const char *base = SDL_GetBasePath();
	std::vector<std::string> candidates;
	if (base)
		for (const char *rel : { "", "Game", "../Game", "../../Game", "rom", "../rom", "../../rom" })
			candidates.push_back(std::string(base) + rel);
	for (const char *rel : { "Game", ".", "rom" }) candidates.push_back(rel);
	for (auto &c : candidates)
	{
		std::ifstream f(c + "/136047-3126.7lm", std::ios::binary);
		if (f) return c;
	}
	return "rom";
}

std::string pref_file(const char *name)
{
	char *p = SDL_GetPrefPath("Atari", "720Degrees");
	std::string s = p ? std::string(p) + name : std::string(name);
	SDL_free(p);
	return s;
}

void load_eeprom(Board &b)
{
	std::ifstream f(pref_file("720.eeprom"), std::ios::binary);
	if (f) f.read((char *)b.eeprom(), 0x200);
}

void save_eeprom(Board &b)
{
	std::ofstream f(pref_file("720.eeprom"), std::ios::binary);
	if (f) f.write((const char *)b.eeprom(), 0x200);
}

}

int main(int argc, char **argv)
{
	Options opt;
	for (int i = 1; i < argc; i++)
	{
		std::string a = argv[i];
		auto next = [&]() { return i + 1 < argc ? std::string(argv[++i]) : std::string(); };
		if (a == "--roms") opt.roms = next();
		else if (a == "--fullscreen") opt.fullscreen = true;
		else if (a == "--scale") opt.scale = std::max(1, atoi(next().c_str()));
		else if (a == "--smooth") opt.smooth = true;
		else if (a == "--dsw0") opt.dsw0 = (int)strtol(next().c_str(), nullptr, 0);
		else if (a == "--dsw1") opt.dsw1 = (int)strtol(next().c_str(), nullptr, 0);
		else if (a == "--invert-rotation") opt.invert_rotation = true;
		else if (a == "--mod") opt.mods.push_back(next());
		else if (a == "--no-mods") opt.no_mods = true;
		else if (a == "--quit-after") opt.quit_after = atof(next().c_str());
	}

	if (!SDL_Init(SDL_INIT_VIDEO | SDL_INIT_AUDIO | SDL_INIT_GAMEPAD))
	{
		SDL_Log("SDL_Init failed: %s", SDL_GetError());
		return 1;
	}

	RomSet roms;
	std::string err;
	const std::string romdir = find_roms(opt.roms);
	if (!roms.load(romdir, err))
	{
		const std::string msg = "Could not load the 720 Degrees ROM set from '" + romdir + "':\n" + err +
			"\n\nPut the ROM files in the 'Game' folder next to 720degrees.exe, or pass --roms <folder>.";
		SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_ERROR, "720 Degrees", msg.c_str(), nullptr);
		return 1;
	}

	SDL_Window *window = nullptr;
	SDL_Renderer *renderer = nullptr;
	if (!SDL_CreateWindowAndRenderer("720 Degrees", 512 * opt.scale, 384 * opt.scale, SDL_WINDOW_RESIZABLE, &window, &renderer))
	{
		SDL_Log("window creation failed: %s", SDL_GetError());
		return 1;
	}
	SDL_SetRenderVSync(renderer, 1);
	SDL_SetRenderLogicalPresentation(renderer, 512, 384, SDL_LOGICAL_PRESENTATION_LETTERBOX);
	if (opt.fullscreen) SDL_SetWindowFullscreen(window, true);
	SDL_Texture *tex = SDL_CreateTexture(renderer, SDL_PIXELFORMAT_ARGB8888, SDL_TEXTUREACCESS_STREAMING, 512, 384);
	SDL_SetTextureScaleMode(tex, opt.smooth ? SDL_SCALEMODE_LINEAR : SDL_SCALEMODE_NEAREST);

	AudioOut audio;
	if (!audio.open((int)std::lround(SoundChips::output_rate())))
		SDL_Log("audio unavailable: %s", SDL_GetError());

	// level mods: Game/mods/*.720mod (unless --no-mods) and --mod <file>
	{
		std::string errors;
		std::vector<std::string> applied;
		if (!opt.no_mods)
		{
			const char *base = SDL_GetBasePath();
			applied = apply_mod_folder(roms, std::string(base ? base : "") + "mods", errors);
		}
		for (const auto &m : opt.mods)
		{
			std::string e;
			if (apply_mod_file(roms, m, e)) applied.push_back(m);
			else errors += m + ": " + e + "\n";
		}
		for (const auto &a : applied) SDL_Log("level mod loaded: %s", a.c_str());
		if (!errors.empty())
			SDL_ShowSimpleMessageBox(SDL_MESSAGEBOX_WARNING, "720 Degrees", ("Some level mods could not be loaded:\n" + errors).c_str(), nullptr);
	}

	auto machine = std::make_unique<NativeMachine>(roms);
	machine->reset();
	load_eeprom(machine->board);
	machine->board.input.dsw0 = (uint8_t)opt.dsw0;
	machine->board.input.dsw1 = (uint8_t)opt.dsw1;

	RotaryController rotary;
	SDL_Gamepad *pad = nullptr;
	bool running = true, paused = false, help = false, mouse_captured = false;
	bool test_switch = false;
	double mouse_accum = 0;
	std::vector<uint32_t> pixels(512 * 384);
	std::vector<int16_t> samples(8192 * 2), frame_audio;
	const double frame_ns = 1e9 * 640.0 * 416.0 / 16000000.0;   // 60.096 Hz
	uint64_t next_frame = SDL_GetTicksNS();
	uint64_t fps_t0 = next_frame;
	int fps_frames = 0;
	bool was_paused = false;
	const uint64_t t_start = next_frame;
	uint64_t total_frames = 0;
	double fps = 0;

	while (running)
	{
		SDL_Event e;
		while (SDL_PollEvent(&e))
		{
			switch (e.type)
			{
			case SDL_EVENT_QUIT:
				running = false;
				break;
			case SDL_EVENT_KEY_DOWN:
				if (e.key.repeat) break;
				switch (e.key.key)
				{
				case SDLK_ESCAPE:
					if (mouse_captured) { mouse_captured = false; SDL_SetWindowRelativeMouseMode(window, false); }
					else running = false;
					break;
				case SDLK_F1: help = !help; break;
				case SDLK_F2: test_switch = !test_switch; break;
				case SDLK_F3:
					save_eeprom(machine->board);
					machine->reset();
					load_eeprom(machine->board);
					machine->board.input.dsw0 = (uint8_t)opt.dsw0;
					machine->board.input.dsw1 = (uint8_t)opt.dsw1;
					break;
				case SDLK_F11:
					SDL_SetWindowFullscreen(window, !(SDL_GetWindowFlags(window) & SDL_WINDOW_FULLSCREEN));
					break;
				case SDLK_RETURN:
					if (e.key.mod & SDL_KMOD_ALT)
						SDL_SetWindowFullscreen(window, !(SDL_GetWindowFlags(window) & SDL_WINDOW_FULLSCREEN));
					break;
				case SDLK_P: paused = !paused; break;
				default: break;
				}
				break;
			case SDL_EVENT_MOUSE_BUTTON_DOWN:
				if (!mouse_captured) { mouse_captured = true; SDL_SetWindowRelativeMouseMode(window, true); }
				break;
			case SDL_EVENT_MOUSE_MOTION:
				if (mouse_captured) mouse_accum += e.motion.xrel;
				break;
			case SDL_EVENT_GAMEPAD_ADDED:
				if (!pad) pad = SDL_OpenGamepad(e.gdevice.which);
				break;
			case SDL_EVENT_GAMEPAD_REMOVED:
				if (pad && SDL_GetGamepadID(pad) == e.gdevice.which) { SDL_CloseGamepad(pad); pad = nullptr; }
				break;
			default:
				break;
			}
		}

		// ---- controls
		const bool *ks = SDL_GetKeyboardState(nullptr);
		int dx = (ks[SDL_SCANCODE_RIGHT] || ks[SDL_SCANCODE_D]) - (ks[SDL_SCANCODE_LEFT] || ks[SDL_SCANCODE_A]);
		int dy = (ks[SDL_SCANCODE_DOWN] || ks[SDL_SCANCODE_S]) - (ks[SDL_SCANCODE_UP] || ks[SDL_SCANCODE_W]);
		double pdx = dx, pdy = dy;
		bool b_jump = ks[SDL_SCANCODE_SPACE] || ks[SDL_SCANCODE_Z];
		bool b_kick = ks[SDL_SCANCODE_LCTRL] || ks[SDL_SCANCODE_X];
		bool coin1 = ks[SDL_SCANCODE_5], coin2 = ks[SDL_SCANCODE_6];
		if (pad)
		{
			const double ax = SDL_GetGamepadAxis(pad, SDL_GAMEPAD_AXIS_LEFTX) / 32767.0;
			const double ay = SDL_GetGamepadAxis(pad, SDL_GAMEPAD_AXIS_LEFTY) / 32767.0;
			if (ax * ax + ay * ay > 0.35 * 0.35) { pdx = ax; pdy = ay; }
			int gdx = SDL_GetGamepadButton(pad, SDL_GAMEPAD_BUTTON_DPAD_RIGHT) - SDL_GetGamepadButton(pad, SDL_GAMEPAD_BUTTON_DPAD_LEFT);
			int gdy = SDL_GetGamepadButton(pad, SDL_GAMEPAD_BUTTON_DPAD_DOWN) - SDL_GetGamepadButton(pad, SDL_GAMEPAD_BUTTON_DPAD_UP);
			if (gdx || gdy) { pdx = gdx; pdy = gdy; }
			b_jump |= SDL_GetGamepadButton(pad, SDL_GAMEPAD_BUTTON_SOUTH);
			b_kick |= SDL_GetGamepadButton(pad, SDL_GAMEPAD_BUTTON_EAST) || SDL_GetGamepadButton(pad, SDL_GAMEPAD_BUTTON_WEST);
			coin1 |= SDL_GetGamepadButton(pad, SDL_GAMEPAD_BUTTON_BACK);
		}
		if (mouse_captured)
		{
			const SDL_MouseButtonFlags mb = SDL_GetMouseState(nullptr, nullptr);
			b_jump |= (mb & SDL_BUTTON_LMASK) != 0;
			b_kick |= (mb & SDL_BUTTON_RMASK) != 0;
		}
		if (pdx != 0 || pdy != 0)
			rotary.set_target_angle(std::atan2(pdx, -pdy) * 180.0 / M_PI * (opt.invert_rotation ? -1 : 1));
		else
			rotary.clear_target();
		const double sgn = opt.invert_rotation ? -1.0 : 1.0;
		if (ks[SDL_SCANCODE_E]) rotary.add_rotation(3.0 * sgn);
		if (ks[SDL_SCANCODE_Q]) rotary.add_rotation(-3.0 * sgn);
		if (mouse_accum != 0) { rotary.add_rotation(mouse_accum * 0.25 * sgn); mouse_accum = 0; }

		// ---- run the game at its native 60.096 Hz
		const uint64_t now = SDL_GetTicksNS();
		if (now > next_frame + (uint64_t)(frame_ns * 8)) next_frame = now;   // resync after a stall
		int frames_run = 0;
		if (was_paused && !paused) audio.restart();
		was_paused = paused;
		while (!paused && now >= next_frame && frames_run < 4)
		{
			rotary.update();
			Inputs &in = machine->board.input;
			in.leta_rotate = rotary.rotate_count();
			in.leta_center = rotary.center_count();
			in.button1 = b_jump;
			in.button2 = b_kick;
			in.coin1 = coin1;
			in.coin2 = coin2;
			in.test = test_switch;
			machine->run_frame();
			next_frame += (uint64_t)frame_ns;
			frames_run++;
			fps_frames++;
			total_frames++;
			// audio
			auto &chips = machine->board.chips();
			frame_audio.clear();
			size_t n;
			while ((n = chips.take_samples(samples.data(), samples.size() / 2)) > 0)
				frame_audio.insert(frame_audio.end(), samples.begin(), samples.begin() + n * 2);
			audio.push(frame_audio.data(), frame_audio.size() / 2);
		}
		if (paused) next_frame = now;

		// ---- present
		machine->board.frame_rgb(pixels.data());
		SDL_UpdateTexture(tex, nullptr, pixels.data(), 512 * 4);
		SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
		SDL_RenderClear(renderer);
		SDL_RenderTexture(renderer, tex, nullptr, nullptr);
		if (now - fps_t0 >= 1000000000ull)
		{
			fps = fps_frames * 1e9 / (double)(now - fps_t0);
			fps_t0 = now;
			fps_frames = 0;
		}
		if (help)
		{
			SDL_SetRenderDrawColor(renderer, 0, 0, 0, 200);
			SDL_SetRenderDrawBlendMode(renderer, SDL_BLENDMODE_BLEND);
			const SDL_FRect r = { 16, 16, 480, 200 };
			SDL_RenderFillRect(renderer, &r);
			SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
			const char *lines[] = {
				"720 DEGREES - native port",
				"Arrows/WASD: point skater   Q/E: rotate",
				"Space/Z: jump   LCtrl/X: kick",
				"5/6: coin   F2: service mode   F3: reset",
				"F11: fullscreen   P: pause   Esc: quit",
				"Mouse: click to capture, move to rotate",
				"Gamepad: stick/dpad, A jump, B kick, Back coin",
			};
			for (int i = 0; i < 7; i++) SDL_RenderDebugText(renderer, 28, 28 + i * 14.0f, lines[i]);
			char buf[64];
			snprintf(buf, sizeof(buf), "%.2f fps%s", fps, paused ? "  PAUSED" : "");
			SDL_RenderDebugText(renderer, 28, 28 + 8 * 14.0f, buf);
		}
		else if (paused)
		{
			SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
			SDL_RenderDebugText(renderer, 232, 8, "PAUSED");
		}
		SDL_RenderPresent(renderer);
		if (opt.quit_after > 0 && (SDL_GetTicksNS() - t_start) / 1e9 >= opt.quit_after) running = false;
	}
	if (opt.quit_after > 0)
	{
		const auto &st = audio.stats;
		printf("%llu frames in %.1f s; audio queue ran dry %llu times in %llu frames (min %.1f ms, mean %.1f ms), %llu dropped\n",
			(unsigned long long)total_frames, (SDL_GetTicksNS() - t_start) / 1e9, (unsigned long long)st.dry,
			(unsigned long long)st.checks, st.checks ? st.min_ms : 0.0, st.checks ? st.sum_ms / st.checks : 0.0,
			(unsigned long long)st.dropped);
	}

	save_eeprom(machine->board);
	machine.reset();
	audio.close();
	if (pad) SDL_CloseGamepad(pad);
	SDL_DestroyTexture(tex);
	SDL_DestroyRenderer(renderer);
	SDL_DestroyWindow(window);
	SDL_Quit();
	return 0;
}
